 panel.Rows.CurrentCell=Row(4).Cells["Product"];All(panel).OfType<Button>().Single(b=>b.Name=="DashboardReady").PerformClick();Pump(()=>fresh.Enabled&&State(store.Get(prep.Id),2)=="PRONTO");Check(State(store.Get(prep.Id),0)=="ENTREGUE"&&State(store.Get(prep.Id),1)=="PRONTO","main READY action affects only the selected rings product");Arrow(3,"ENTREGUE");Check(State(store.Get(prep.Id),2)=="PRONTO","delivering sushi keeps ready rings awaiting delivery");var blocked=store.Quote(prep.Id);Reject(()=>KitchenStore.SelectItems(blocked,blocked.Items.Select(i=>new KitchenPayQuantity(i.OrderId,i.Position,i.Quantity)).ToArray(),true),"ready but undelivered rings still block full payment");
