 var final=store.Quote(prep.Id);var bill=KitchenStore.SelectItems(final,final.Items.Select(i=>new KitchenPayQuantity(i.OrderId,i.Position,i.Quantity)).ToArray(),true);Check(bill.Total==70,"final bill contains only unpaid delivered quantities");store.Receive(bill,new[]{new KitchenPayment("PIX",70)},"QA");Check(KitchenTablesView.State(store.ListActive(),1)=="LIVRE"&&Count("SELECT COUNT(*) FROM sales")==2&&Value("SELECT stock FROM products WHERE id=2")==98,"table closes only after all individual deliveries and outstanding balances are paid");
 var cancel=store.Submit(id,Draft("Mesa 03",false,pizza,rings));cancel=store.ChangeItemStatus(cancel.Id,0,cancel.Revision,"PRONTO","QA",Guid.NewGuid());var beforeCancel=Money();cancel=store.CancelItem(cancel.Id,0,cancel.Revision,"QA",Guid.NewGuid());Check(cancel.Items.Length==1&&State(cancel,1)=="AGUARDANDO"&&Money()==beforeCancel,"cancelling one ready product preserves waiting sibling and completed finance");Check(Convert.ToString(Sql("SELECT payload_hash FROM kitchen_orders_v1 WHERE id='"+prep.Id+"'"))==payload,"original order payload and traceability remain intact");form.Close();Check(Convert.ToString(Sql("PRAGMA quick_check"))=="ok","database integrity passes after migration individual states payment and cancellation");
